insert into public.sources (id, name, kind, role, status, enabled, refresh_minutes, homepage, docs_url, notes, credential_env, runs_in, config) values
  ('hn_show', 'Hacker News – Show HN', 'api', 'discovery', 'operational', true, 60, 'https://news.ycombinator.com/show', 'https://hn.algolia.com/api', 'Official Algolia HN Search API. Points and comments are platform metrics, not business metrics.', '{}', '{"server","browser"}', '{"minPoints":5,"lookbackHours":48}'::jsonb),
  ('producthunt_feed', 'Product Hunt – public feed', 'rss', 'discovery', 'operational', true, 120, 'https://www.producthunt.com/', 'https://www.producthunt.com/feed', 'Public Atom feed of recent launches (name, tagline, hunter, date). The feed has no website URL or vote counts; Product Hunt pages are bot-protected and are not scraped. Products are identified by their Product Hunt slug until another source supplies a domain.', '{}', '{"server"}', '{}'::jsonb),
  ('producthunt_api', 'Product Hunt – GraphQL API', 'api', 'discovery', 'requires_credentials', false, 120, 'https://www.producthunt.com/', 'https://api.producthunt.com/v2/docs', 'Official API v2 with vote counts, topics and website. Requires a developer token (PRODUCT_HUNT_TOKEN). Commercial use requires Product Hunt approval.', '{"PRODUCT_HUNT_TOKEN"}', '{"server"}', '{}'::jsonb),
  ('github_rising', 'GitHub – rising new repositories', 'api', 'discovery', 'operational', true, 360, 'https://github.com/trending', 'https://docs.github.com/en/rest/search/search#search-repositories', 'GitHub has no Trending API. This connector uses the official Search API for repositories created in the last N days, ranked by stars. Stars are a platform metric. Optional GITHUB_TOKEN raises rate limits.', '{}', '{"server","browser"}', '{"days":7,"minStars":100}'::jsonb),
  ('trustmrr', 'TrustMRR', 'sitemap', 'both', 'operational', true, 360, 'https://trustmrr.com/', 'https://trustmrr.com/startup-sitemap.xml', 'Startups connect their payment provider (e.g. Stripe) and TrustMRR publishes verified revenue. Signal reads the public startup sitemap and schema.org data on each public page (robots.txt allows all). Highest-trust revenue source.', '{}', '{"server"}', '{"pagesPerRun":30}'::jsonb),
  ('quietmoney', 'QuietMoney', 'sitemap', 'both', 'operational', true, 720, 'https://quietmoney.000ooo.ooo/', 'https://quietmoney.000ooo.ooo/sitemap.xml', 'Profiles of quietly profitable sites: checkout-visit estimates (Similarweb-based), traffic sources, growth story and alternatives. Read from the public sitemap and schema.org data (robots.txt allows all except /api/). Pro-only sections are never requested. All figures are third-party estimates.', '{}', '{"server"}', '{"pagesPerRun":25}'::jsonb),
  ('cashflowing', 'Cashflowing', 'public_page', 'enrichment', 'operational', true, 10080, 'https://cashflowing.app/', 'https://cashflowing.app/en/ranking', 'Per-domain lookup of modelled checkout-page traffic (by month) and checkout provider. Used for enrichment only: its sitemap is dominated by large retailers. The on-page "revenue estimator" is an assumptions slider and is never ingested. Full dataset is licensed (paid).', '{}', '{"server"}', '{}'::jsonb),
  ('website', 'Founder website', 'public_page', 'enrichment', 'operational', true, 10080, '', null, 'Reads the product''s own homepage plus About/Pricing pages when linked (robots.txt checked first). Figures stated there are founder-reported and never treated as verified.', '{}', '{"server"}', '{}'::jsonb),
  ('reddit', 'Reddit – r/SaaS, r/SideProject, r/indiehackers', 'api', 'discovery', 'requires_credentials', false, 120, 'https://www.reddit.com/r/SideProject/', 'https://support.reddithelp.com/hc/en-us/articles/16160319875092-Reddit-Data-API-Wiki', 'Official Reddit Data API via OAuth (REDDIT_CLIENT_ID / REDDIT_CLIENT_SECRET). Anonymous JSON/RSS access is blocked. Commercial use may require an agreement with Reddit. Revenue claims in posts are founder-reported, low confidence.', '{"REDDIT_CLIENT_ID","REDDIT_CLIENT_SECRET"}', '{"server"}', '{"subreddits":["SaaS","SideProject","indiehackers"],"minScore":5}'::jsonb),
  ('meta_ads', 'Meta Ad Library API', 'api', 'enrichment', 'requires_credentials', false, 1440, 'https://www.facebook.com/ads/library/', 'https://www.facebook.com/ads/library/api/', 'Official Ad Library API (ads_archive). Requires a user access token with identity verification (META_ADS_TOKEN). Coverage: ads delivered in the EU (DSA transparency) plus political/issue ads. Spend and performance are not available for commercial ads and are never inferred.', '{"META_ADS_TOKEN"}', '{"server"}', '{"countries":["FR","DE","ES","IT","NL","IE"]}'::jsonb),
  ('similarweb', 'Similarweb DigitalRank API', 'licensed', 'enrichment', 'requires_credentials', false, 10080, 'https://www.similarweb.com/', 'https://developers.similarweb.com/', 'Global rank via the DigitalRank API (SIMILARWEB_API_KEY). Full traffic data requires a paid Similarweb plan. All values are estimates. Untested in this build (no key available).', '{"SIMILARWEB_API_KEY"}', '{"server"}', '{}'::jsonb),
  ('starter_story', 'Starter Story', 'manual', 'both', 'manual', false, 0, 'https://www.starterstory.com/', null, 'No API or RSS feed; interviews are largely behind a paid membership. Paste an article URL into Add Product to attach it manually (only public metadata is read).', '{}', '{}', '{}'::jsonb),
  ('indie_hackers', 'Indie Hackers', 'manual', 'both', 'unsupported', false, 0, 'https://www.indiehackers.com/', null, 'No public API; feed returns 403 and robots.txt disallows AI/automated crawlers. Not collected automatically.', '{}', '{}', '{}'::jsonb),
  ('acquire', 'Acquire.com', 'manual', 'both', 'unsupported', false, 0, 'https://acquire.com/', null, 'Listing financials are gated behind buyer accounts/NDAs. No public API.', '{}', '{}', '{}'::jsonb),
  ('exploding_topics', 'Exploding Topics', 'licensed', 'discovery', 'licensed', false, 1440, 'https://explodingtopics.com/', 'https://explodingtopics.com/api', 'Paid API on Business plans (recurring cost). Not implemented until licensed.', '{"EXPLODING_TOPICS_API_KEY"}', '{"server"}', '{}'::jsonb),
  ('google_trends', 'Google Trends', 'api', 'enrichment', 'unsupported', false, 0, 'https://trends.google.com/trends/', 'https://developers.google.com/search/apis/trends', 'Official Trends API is in limited alpha (application required). Unofficial scraping violates the terms, so it is not used.', '{}', '{}', '{}'::jsonb),
  ('tiktok_creative', 'TikTok Creative Center / Commercial Content API', 'api', 'enrichment', 'unsupported', false, 0, 'https://ads.tiktok.com/business/creativecenter/', 'https://developers.tiktok.com/products/commercial-content-api', 'Creative Center has no public API. The Commercial Content API (EU ads) requires an approved application.', '{"TIKTOK_CCA_TOKEN"}', '{}', '{}'::jsonb),
  ('google_ads_transparency', 'Google Ads Transparency Center', 'licensed', 'enrichment', 'unsupported', false, 0, 'https://adstransparency.google.com/', 'https://console.cloud.google.com/marketplace/product/bigquery-public-data/google-ads-transparency-center', 'No API; the legitimate route is the BigQuery public dataset (per-query cost). Designed, not implemented.', '{"GCP_SERVICE_ACCOUNT_JSON"}', '{}', '{}'::jsonb),
  ('manual', 'Manual submission', 'manual', 'both', 'operational', true, 0, '', null, 'Products added by pasting a URL (Add Product).', '{}', '{"server"}', '{}'::jsonb)
